#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int>p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>>ops;
    auto apply=[&](int x,int y){
        vector<int>np(n);
        for(int i=0;i<y;i++) np[i]=p[n-y+i];
        for(int i=0;i<n-x-y;i++) np[y+i]=p[x+i];
        for(int i=0;i<x;i++) np[n-x+i]=p[i];
        p=np;
        ops.push_back({x,y});
    };
    // Place elements 1,2,...,n one at a time to the end (rightmost)
    // Actually, let's try: repeatedly find and place using at most 2 ops per element
    for(int placed=0; placed<n; placed++){
        int val=placed+1;
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==val){pos=i;break;}
        if(pos==placed) continue;
        // Move val to front first: x=pos, y=n-pos => but need x>=1,y>=1
        if(pos>0 && pos<n){
            apply(pos, n-pos); // val goes to position 0
            pos=0;
        }
        // Now val is at position 0, move to position placed
        // x=1,y=n-placed => val goes to pos 0 in last y, new pos=0. Hmm
        if(placed>0 && placed<n){
            apply(placed,1); // pos 0 -> n-placed+0 = n-placed. Not right
            // Actually: pos 0 is in [0, x-1]=[0,placed-1], new pos = n-placed+0=n-placed. Wrong.
            // We need pos 0 -> placed. pos 0 in [0,x-1] -> n-x+0. So n-x=placed, x=n-placed. y can be 1..placed. 
            apply(n-placed, placed);
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
